function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // book
  ctx.fillStyle = '#663300';
  ctx.fillRect(W/2-50, H/2-75, 100, 10);
  ctx.fillRect(W/2-50, H/2-50, 100, 10);
  ctx.fillRect(W/2-50, H/2-25, 100, 10);
  ctx.fillRect(W/2-50, H/2, 100, 10);
  ctx.fillRect(W/2-50, H/2+25, 100, 10);
  ctx.fillStyle = '#000000';
  ctx.lineWidth = 3;
  ctx.strokeRect(W/2-50, H/2-75, 100, 100);

  // stick figure
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2+100, H/2, 20, 0, Math.PI*2);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2+100, H/2+20);
  ctx.lineTo(W/2+100, H/2+50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2+100, H/2+30);
  ctx.lineTo(W/2+80, H/2+50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2+100, H/2+30);
  ctx.lineTo(W/2+120, H/2+50);
  ctx.stroke();

  // lesson text
  ctx.font = '20px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = '#000000';
  ctx.fillText('LESSON', W/2+150, H/2+75);

  // wisdom text
  ctx.font = '20px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = '#000000';
  ctx.fillText('WISDOM', W/2+150, H/2+100);

  // applying text
  ctx.font = '20px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = '#000000';
  ctx.fillText('APPLYING', W/2+150, H/2+125);

  // life text
  ctx.font = '20px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = '#000000';
  ctx.fillText('LIFE', W/2+150, H/2+150);

  // 1345 text
  ctx.font = '20px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = '#000000';
  ctx.fillText('1345', W/2+150, H/2+175);

  // animation
  ctx.beginPath();
  ctx.arc(W/2+100, H/2, 20+10*Math.sin(t), 0, Math.PI*2);
  ctx.stroke();

  ctx.restore();
}
